def git_tree(owner, repo, branch=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0140000" if __import__("os").path.isdir("./environment_mix/0140000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_request_logs():
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _new_id(prefix):
        # id convention is opaque; keep stable-ish prefixes used in dataset
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%y%m%d%H%M%S')}{secrets.token_hex(10)}"

    def _log_request(status, error_code=None, message=None, meta=None, t0=None):
        logs_file = _ensure_request_logs()
        logs = _load(logs_file)
        latency_ms = int((time.time() - t0) * 1000) if isinstance(t0, (int, float)) else None
        row = {
            "id": _new_id("req"),
            "endpoint": "git_tree",
            "credential": None,
            "status": status,
            "error_code": error_code,
            "message": message,
            "meta": meta,
            "latency_ms": latency_ms,
            "created_at": _now(),
        }
        logs.append(row)
        _save(logs_file, logs)

    def _enforce_rate_limit(t0):
        # Simple per-endpoint sliding window based on request_logs if present.
        logs_file = _ensure_request_logs()
        logs = _load(logs_file)
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != "git_tree":
                continue
            ts = _dt(r.get("created_at"))
            if ts and ts >= cutoff:
                recent += 1
        if recent >= 120:
            _log_request("error", "RATE_LIMIT", "Rate limit exceeded", t0=t0)
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    t0 = time.time()

    # Validate inputs
    if not isinstance(owner, str) or not owner.strip():
        _log_request("error", "VALIDATION_ERROR", "owner must be a non-empty string.", t0=t0)
        return _err("VALIDATION_ERROR", "owner must be a non-empty string.")
    if not isinstance(repo, str) or not repo.strip():
        _log_request("error", "VALIDATION_ERROR", "repo must be a non-empty string.", t0=t0)
        return _err("VALIDATION_ERROR", "repo must be a non-empty string.")
    if branch is not None and (not isinstance(branch, str) or not branch.strip()):
        _log_request("error", "VALIDATION_ERROR", "branch must be a non-empty string or null.", t0=t0)
        return _err("VALIDATION_ERROR", "branch must be a non-empty string or null.")

    rl = _enforce_rate_limit(t0)
    if rl:
        return rl

    repos = _load("github_repositories.json")
    branches = _load("repo_branches.json")
    snapshots = _load("repo_snapshots.json")
    entries = _load("snapshot_entries.json")
    jobs = _load("fetch_jobs.json")

    now = _now()

    # Resolve repository: accept either repo name OR a repository id (audit defect showed id passed as repo param)
    repo_row = None
    for r in repos:
        if not isinstance(r, dict):
            continue
        if r.get("owner") == owner and r.get("name") == repo:
            repo_row = r
            break
    if repo_row is None:
        for r in repos:
            if not isinstance(r, dict):
                continue
            if r.get("id") == repo:
                # If id matches, accept it regardless of owner mismatch (caller may still pass owner)
                repo_row = r
                break

    # If missing, create it (business rule for git_summary says create; for tree/files we also must accept and persist)
    if repo_row is None:
        # Enforce owner/repo non-empty already. Also enforce unique(owner,name)
        repo_id = _new_id("gir_repo")
        repo_row = {
            "id": repo_id,
            "owner": owner,
            "name": repo,
            "full_name": f"{owner}/{repo}",
            "default_branch": None,
            "visibility": "unknown",
            "last_seen_at": now,
            "created_at": now,
            "updated_at": now,
        }
        repos.append(repo_row)
        _save("github_repositories.json", repos)
    else:
        repo_row["last_seen_at"] = now
        repo_row["updated_at"] = now
        _save("github_repositories.json", repos)

    repository_id = repo_row.get("id")

    # Resolve branch_name
    branch_name = branch if branch is not None else repo_row.get("default_branch")
    # If still unknown, try to find default branch row for repo, else create a placeholder default branch row.
    default_branch_row = None
    if not branch_name:
        for b in branches:
            if isinstance(b, dict) and b.get("repository_id") == repository_id and b.get("is_default") is True:
                default_branch_row = b
                break
        if default_branch_row:
            branch_name = default_branch_row.get("name")

    if not branch_name:
        # Create a default branch placeholder named "main" (best-effort) and mark repo default_branch too.
        # This matches "create/refresh once discovered" behaviour; offline store can't truly discover.
        branch_name = "main"
        repo_row["default_branch"] = branch_name
        repo_row["updated_at"] = now
        _save("github_repositories.json", repos)

    # Ensure repo_branches row exists for branch_name (exact match when branch provided)
    branch_row = None
    for b in branches:
        if not isinstance(b, dict):
            continue
        if b.get("repository_id") == repository_id and b.get("name") == branch_name:
            branch_row = b
            break

    if branch_row is None:
        # Create branch with unknown head_commit_sha; update last_refreshed_at.
        # If branch is None and this is presumed default, mark is_default=true and clear any other default.
        is_default = (branch is None)
        if is_default:
            for b in branches:
                if isinstance(b, dict) and b.get("repository_id") == repository_id and b.get("is_default") is True:
                    b["is_default"] = False
                    b["updated_at"] = now
        branch_row = {
            "id": _new_id("gir_br"),
            "repository_id": repository_id,
            "name": branch_name,
            "head_commit_sha": None,
            "is_default": True if is_default else False,
            "last_refreshed_at": now,
            "created_at": now,
            "updated_at": now,
        }
        branches.append(branch_row)
        _save("repo_branches.json", branches)
    else:
        # If branch explicitly requested, it must match exactly (it does, since we looked up exact name).
        branch_row["last_refreshed_at"] = now
        branch_row["updated_at"] = now
        # If branch is None and repo_default matches, mark is_default (enforce single default)
        if branch is None:
            for b in branches:
                if isinstance(b, dict) and b.get("repository_id") == repository_id:
                    if b.get("id") == branch_row.get("id"):
                        continue
                    if b.get("is_default") is True:
                        b["is_default"] = False
                        b["updated_at"] = now
            branch_row["is_default"] = True
        _save("repo_branches.json", branches)

    head_sha = branch_row.get("head_commit_sha")
    if not isinstance(head_sha, str) or not head_sha:
        # Offline best-effort pin: deterministic-ish placeholder so uniqueness works and snapshot pin is stable.
        # Real backend would fetch from GitHub; here we must still create/queue snapshot consistently.
        head_sha = f"unknown-{repository_id[:8]}-{branch_name[:24]}"
        branch_row["head_commit_sha"] = head_sha
        branch_row["last_refreshed_at"] = now
        branch_row["updated_at"] = now
        _save("repo_branches.json", branches)

    # Find ready snapshot for (repository_id, branch_name, head_sha)
    snap = None
    for s in snapshots:
        if not isinstance(s, dict):
            continue
        if s.get("repository_id") == repository_id and s.get("branch_name") == branch_name and s.get("commit_sha") == head_sha and s.get("status") == "ready":
            snap = s
            break

    # If no ready snapshot, create queued snapshot (dedupe by unique constraint) and enqueue build job
    if snap is None:
        existing = None
        for s in snapshots:
            if not isinstance(s, dict):
                continue
            if s.get("repository_id") == repository_id and s.get("branch_name") == branch_name and s.get("commit_sha") == head_sha:
                existing = s
                break
        if existing is None:
            snap = {
                "id": _new_id("gir_snap"),
                "repository_id": repository_id,
                "branch_name": branch_name,
                "commit_sha": head_sha,
                "readme_path": None,
                "readme_summary": None,
                "total_files": 0,
                "total_tokens": 0,
                "tokenizer": "unknown",
                "status": "queued",
                "error_message": None,
                "source_fetched_at": None,
                "expires_at": None,
                "created_at": now,
                "updated_at": now,
            }
            snapshots.append(snap)
            _save("repo_snapshots.json", snapshots)
        else:
            snap = existing
            # If expired, allow transition expired -> queued only
            if snap.get("status") == "expired":
                snap["status"] = "queued"
                snap["error_message"] = None
                snap["updated_at"] = now
                _save("repo_snapshots.json", snapshots)

        # Ensure a build_snapshot job exists queued/running for this snapshot (dedupe)
        have_job = False
        for j in jobs:
            if not isinstance(j, dict):
                continue
            if j.get("job_type") == "build_snapshot" and j.get("snapshot_id") == snap.get("id") and j.get("status") in ("queued", "running"):
                have_job = True
                break
        if not have_job:
            jobs.append({
                "id": _new_id("gir_job"),
                "repository_id": repository_id,
                "snapshot_id": snap.get("id"),
                "job_type": "build_snapshot",
                "requested_branch": branch_name,
                "requested_file_paths": None,
                "status": "queued",
                "attempt": 1,
                "http_status": None,
                "rate_limit_remaining": None,
                "error_message": None,
                "started_at": None,
                "finished_at": None,
                "created_at": now,
                "updated_at": now,
            })
            _save("fetch_jobs.json", jobs)

        # Return empty tree for now (no partial results from non-ready snapshots by rule)
        _log_request("ok", meta={"repository_id": repository_id, "snapshot_id": snap.get("id"), "snapshot_status": snap.get("status")}, t0=t0)
        return {
            "repository": {"id": repository_id, "owner": repo_row.get("owner"), "name": repo_row.get("name"), "full_name": repo_row.get("full_name")},
            "branch": {"name": branch_name, "head_commit_sha": head_sha},
            "snapshot": {"id": snap.get("id"), "commit_sha": head_sha, "status": snap.get("status")},
            "tree": [],
            "meta": {"served_from_cache": False, "note": "Snapshot not ready; build queued."}
        }

    # Snapshot is ready; return tree entries
    snap_id = snap.get("id")
    tree = []
    for e in entries:
        if not isinstance(e, dict):
            continue
        if e.get("snapshot_id") != snap_id:
            continue
        if e.get("entry_type") in ("file", "dir", "symlink", "submodule"):
            tree.append(e)
    tree.sort(key=lambda r: (r.get("path") or ""))

    _log_request("ok", meta={"repository_id": repository_id, "snapshot_id": snap_id, "returned": len(tree)}, t0=t0)
    return {
        "repository": {"id": repository_id, "owner": repo_row.get("owner"), "name": repo_row.get("name"), "full_name": repo_row.get("full_name")},
        "branch": {"name": branch_name, "head_commit_sha": head_sha},
        "snapshot": {"id": snap_id, "commit_sha": head_sha, "status": "ready"},
        "tree": tree,
        "meta": {"total": len(tree), "served_from_cache": True}
    }

def git_files(owner, repo, file_paths, branch=None, **_extra):
    import json, os, datetime, time, secrets, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0140000" if __import__("os").path.isdir("./environment_mix/0140000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_request_logs():
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%y%m%d%H%M%S')}{secrets.token_hex(10)}"

    def _log_request(status, error_code=None, message=None, meta=None, t0=None):
        logs_file = _ensure_request_logs()
        logs = _load(logs_file)
        latency_ms = int((time.time() - t0) * 1000) if isinstance(t0, (int, float)) else None
        logs.append({
            "id": _new_id("req"),
            "endpoint": "git_files",
            "credential": None,
            "status": status,
            "error_code": error_code,
            "message": message,
            "meta": meta,
            "latency_ms": latency_ms,
            "created_at": _now(),
        })
        _save(logs_file, logs)

    def _enforce_rate_limit(t0):
        logs_file = _ensure_request_logs()
        logs = _load(logs_file)
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != "git_files":
                continue
            ts = _dt(r.get("created_at"))
            if ts and ts >= cutoff:
                recent += 1
        if recent >= 120:
            _log_request("error", "RATE_LIMIT", "Rate limit exceeded", t0=t0)
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    t0 = time.time()

    # Validate inputs
    if not isinstance(owner, str) or not owner.strip():
        _log_request("error", "VALIDATION_ERROR", "owner must be a non-empty string.", t0=t0)
        return _err("VALIDATION_ERROR", "owner must be a non-empty string.")
    if not isinstance(repo, str) or not repo.strip():
        _log_request("error", "VALIDATION_ERROR", "repo must be a non-empty string.", t0=t0)
        return _err("VALIDATION_ERROR", "repo must be a non-empty string.")
    if branch is not None and (not isinstance(branch, str) or not branch.strip()):
        _log_request("error", "VALIDATION_ERROR", "branch must be a non-empty string or null.", t0=t0)
        return _err("VALIDATION_ERROR", "branch must be a non-empty string or null.")
    if not isinstance(file_paths, list) or len(file_paths) == 0 or any((not isinstance(p, str) or not p.strip()) for p in file_paths):
        _log_request("error", "VALIDATION_ERROR", "file_paths must be a non-empty array of non-empty strings.", t0=t0)
        return _err("VALIDATION_ERROR", "file_paths must be a non-empty array of non-empty strings.")

    rl = _enforce_rate_limit(t0)
    if rl:
        return rl

    repos = _load("github_repositories.json")
    branches = _load("repo_branches.json")
    snapshots = _load("repo_snapshots.json")
    entries = _load("snapshot_entries.json")
    jobs = _load("fetch_jobs.json")

    now = _now()

    # Resolve repository by (owner,name) OR by id passed in repo param
    repo_row = None
    for r in repos:
        if isinstance(r, dict) and r.get("owner") == owner and r.get("name") == repo:
            repo_row = r
            break
    if repo_row is None:
        for r in repos:
            if isinstance(r, dict) and r.get("id") == repo:
                repo_row = r
                break

    # Create if missing (consistent with acceptance/persistence requirement)
    if repo_row is None:
        repo_row = {
            "id": _new_id("gir_repo"),
            "owner": owner,
            "name": repo,
            "full_name": f"{owner}/{repo}",
            "default_branch": None,
            "visibility": "unknown",
            "last_seen_at": now,
            "created_at": now,
            "updated_at": now,
        }
        repos.append(repo_row)
        _save("github_repositories.json", repos)
    else:
        repo_row["last_seen_at"] = now
        repo_row["updated_at"] = now
        _save("github_repositories.json", repos)

    repository_id = repo_row.get("id")

    # Resolve branch_name
    branch_name = branch if branch is not None else repo_row.get("default_branch")
    if not branch_name:
        for b in branches:
            if isinstance(b, dict) and b.get("repository_id") == repository_id and b.get("is_default") is True:
                branch_name = b.get("name")
                break
    if not branch_name:
        branch_name = "main"
        repo_row["default_branch"] = branch_name
        repo_row["updated_at"] = now
        _save("github_repositories.json", repos)

    # Ensure branch row exists
    branch_row = None
    for b in branches:
        if isinstance(b, dict) and b.get("repository_id") == repository_id and b.get("name") == branch_name:
            branch_row = b
            break
    if branch_row is None:
        is_default = (branch is None)
        if is_default:
            for b in branches:
                if isinstance(b, dict) and b.get("repository_id") == repository_id and b.get("is_default") is True:
                    b["is_default"] = False
                    b["updated_at"] = now
        branch_row = {
            "id": _new_id("gir_br"),
            "repository_id": repository_id,
            "name": branch_name,
            "head_commit_sha": None,
            "is_default": True if is_default else False,
            "last_refreshed_at": now,
            "created_at": now,
            "updated_at": now,
        }
        branches.append(branch_row)
        _save("repo_branches.json", branches)
    else:
        branch_row["last_refreshed_at"] = now
        branch_row["updated_at"] = now
        if branch is None:
            for b in branches:
                if isinstance(b, dict) and b.get("repository_id") == repository_id:
                    if b.get("id") != branch_row.get("id") and b.get("is_default") is True:
                        b["is_default"] = False
                        b["updated_at"] = now
            branch_row["is_default"] = True
        _save("repo_branches.json", branches)

    head_sha = branch_row.get("head_commit_sha")
    if not isinstance(head_sha, str) or not head_sha:
        head_sha = f"unknown-{repository_id[:8]}-{branch_name[:24]}"
        branch_row["head_commit_sha"] = head_sha
        branch_row["last_refreshed_at"] = now
        branch_row["updated_at"] = now
        _save("repo_branches.json", branches)

    # Locate ready snapshot for this commit
    snap = None
    for s in snapshots:
        if isinstance(s, dict) and s.get("repository_id") == repository_id and s.get("branch_name") == branch_name and s.get("commit_sha") == head_sha and s.get("status") == "ready":
            snap = s
            break

    if snap is None:
        # Create/dedupe snapshot and build job; return per-path results indicating snapshot not ready.
        existing = None
        for s in snapshots:
            if isinstance(s, dict) and s.get("repository_id") == repository_id and s.get("branch_name") == branch_name and s.get("commit_sha") == head_sha:
                existing = s
                break
        if existing is None:
            snap = {
                "id": _new_id("gir_snap"),
                "repository_id": repository_id,
                "branch_name": branch_name,
                "commit_sha": head_sha,
                "readme_path": None,
                "readme_summary": None,
                "total_files": 0,
                "total_tokens": 0,
                "tokenizer": "unknown",
                "status": "queued",
                "error_message": None,
                "source_fetched_at": None,
                "expires_at": None,
                "created_at": now,
                "updated_at": now,
            }
            snapshots.append(snap)
            _save("repo_snapshots.json", snapshots)
        else:
            snap = existing
            if snap.get("status") == "expired":
                snap["status"] = "queued"
                snap["error_message"] = None
                snap["updated_at"] = now
                _save("repo_snapshots.json", snapshots)

        have_job = False
        for j in jobs:
            if isinstance(j, dict) and j.get("job_type") == "build_snapshot" and j.get("snapshot_id") == snap.get("id") and j.get("status") in ("queued", "running"):
                have_job = True
                break
        if not have_job:
            jobs.append({
                "id": _new_id("gir_job"),
                "repository_id": repository_id,
                "snapshot_id": snap.get("id"),
                "job_type": "build_snapshot",
                "requested_branch": branch_name,
                "requested_file_paths": list(file_paths),
                "status": "queued",
                "attempt": 1,
                "http_status": None,
                "rate_limit_remaining": None,
                "error_message": None,
                "started_at": None,
                "finished_at": None,
                "created_at": now,
                "updated_at": now,
            })
            _save("fetch_jobs.json", jobs)

        results = []
        for p in file_paths:
            results.append({
                "path": p,
                "status": "snapshot_not_ready",
                "content_status": "absent",
                "content_text": None,
                "content_bytes_base64": None,
                "error": {"code": "CONFLICT", "message": "Snapshot is not ready; build queued."}
            })
        _log_request("ok", meta={"repository_id": repository_id, "snapshot_id": snap.get("id"), "snapshot_status": snap.get("status"), "returned": len(results)}, t0=t0)
        return {
            "repository": {"id": repository_id, "owner": repo_row.get("owner"), "name": repo_row.get("name"), "full_name": repo_row.get("full_name")},
            "branch": {"name": branch_name, "head_commit_sha": head_sha},
            "snapshot": {"id": snap.get("id"), "commit_sha": head_sha, "status": snap.get("status")},
            "files": results,
            "meta": {"served_from_cache": False}
        }

    snap_id = snap.get("id")

    # Map entries by path for snapshot
    ent_by_path = {}
    for e in entries:
        if isinstance(e, dict) and e.get("snapshot_id") == snap_id:
            ent_by_path[e.get("path")] = e

    # Mutations of content are allowed even after ready (rule: structure immutable; content can be cached)
    # When caching, set fetching then available/binary/too_large.
    MAX_BYTES = 1024 * 1024  # 1MB safety cap offline
    results = []
    any_mutation = False

    def _estimate_tokens(text):
        if not isinstance(text, str):
            return 0
        # Rough estimate: 4 chars per token
        return max(0, (len(text) + 3) // 4)

    for p in file_paths:
        e = ent_by_path.get(p)
        if not e:
            results.append({
                "path": p,
                "status": "not_found",
                "content_status": "absent",
                "content_text": None,
                "content_bytes_base64": None,
                "error": {"code": "NOT_FOUND", "message": "Path not found in snapshot."}
            })
            continue
        if e.get("entry_type") != "file":
            results.append({
                "path": p,
                "status": "not_a_file",
                "content_status": e.get("content_status"),
                "content_text": None,
                "content_bytes_base64": None,
                "error": {"code": "CONFLICT", "message": "Requested path is not a file."}
            })
            continue

        # Serve cached if available
        cstat = e.get("content_status")
        if cstat == "available" and isinstance(e.get("content_text"), str):
            results.append({
                "path": p,
                "status": "ok",
                "content_status": "available",
                "content_text": e.get("content_text"),
                "content_bytes_base64": e.get("content_bytes_base64"),
            })
            continue
        if cstat in ("too_large", "binary", "error"):
            results.append({
                "path": p,
                "status": "ok",
                "content_status": cstat,
                "content_text": None,
                "content_bytes_base64": e.get("content_bytes_base64"),
                "error": {"code": "CONFLICT", "message": f"Content not available due to content_status={cstat}."}
            })
            continue

        # Fetching simulation: mark fetching then "retrieve" (offline: can't call GitHub)
        e["content_status"] = "fetching"
        e["updated_at"] = now
        any_mutation = True

        # Offline deterministic placeholder content; size/binary checks apply.
        placeholder = f"# Offline cached placeholder\n# {repo_row.get('full_name')}@{head_sha}\n# path: {p}\n"
        raw_bytes = placeholder.encode("utf-8")

        size = e.get("size_bytes")
        if isinstance(size, int) and size > MAX_BYTES:
            e["content_status"] = "too_large"
            e["content_text"] = None
            e["content_bytes_base64"] = None
            e["content_fetched_at"] = now
            e["tokens_estimate"] = None
            e["updated_at"] = now
            results.append({
                "path": p,
                "status": "ok",
                "content_status": "too_large",
                "content_text": None,
                "content_bytes_base64": None,
                "error": {"code": "CONFLICT", "message": "File exceeds maximum cache size."}
            })
            continue

        # Detect binary (very rough): presence of NUL in bytes
        if b"\x00" in raw_bytes:
            e["content_status"] = "binary"
            e["content_text"] = None
            # store optional base64 for binary; keep null by default
            e["content_bytes_base64"] = base64.b64encode(raw_bytes[:4096]).decode("ascii")
            e["content_fetched_at"] = now
            e["tokens_estimate"] = None
            e["updated_at"] = now
            results.append({
                "path": p,
                "status": "ok",
                "content_status": "binary",
                "content_text": None,
                "content_bytes_base64": e.get("content_bytes_base64"),
                "error": {"code": "CONFLICT", "message": "Binary file; text content not stored."}
            })
            continue

        # Success: available
        text = raw_bytes.decode("utf-8", errors="replace")
        e["content_status"] = "available"
        e["content_text"] = text
        e["content_bytes_base64"] = None
        e["content_fetched_at"] = now
        e["tokens_estimate"] = _estimate_tokens(text)
        e["updated_at"] = now
        results.append({
            "path": p,
            "status": "ok",
            "content_status": "available",
            "content_text": text,
            "content_bytes_base64": None,
        })

    if any_mutation:
        # Persist updated entries
        # entries is a list; we edited dicts in place, so just save.
        _save("snapshot_entries.json", entries)

        # Update snapshot total_tokens best-effort (must be >= 0)
        total_tokens = 0
        total_files = 0
        for e in entries:
            if not isinstance(e, dict) or e.get("snapshot_id") != snap_id:
                continue
            if e.get("entry_type") == "file":
                total_files += 1
            te = e.get("tokens_estimate")
            if isinstance(te, int) and te >= 0:
                total_tokens += te
        # Only update if snapshot is ready (it is) and keep non-negative
        for s in snapshots:
            if isinstance(s, dict) and s.get("id") == snap_id:
                s["total_files"] = max(0, total_files)
                s["total_tokens"] = max(0, total_tokens)
                s["updated_at"] = now
                break
        _save("repo_snapshots.json", snapshots)

        # Enqueue a fetch_file_contents job as observable dynamic for cache misses
        jobs.append({
            "id": _new_id("gir_job"),
            "repository_id": repository_id,
            "snapshot_id": snap_id,
            "job_type": "fetch_file_contents",
            "requested_branch": branch_name,
            "requested_file_paths": list(file_paths),
            "status": "succeeded",
            "attempt": 1,
            "http_status": 200,
            "rate_limit_remaining": None,
            "error_message": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        })
        _save("fetch_jobs.json", jobs)

    _log_request("ok", meta={"repository_id": repository_id, "snapshot_id": snap_id, "returned": len(results)}, t0=t0)
    return {
        "repository": {"id": repository_id, "owner": repo_row.get("owner"), "name": repo_row.get("name"), "full_name": repo_row.get("full_name")},
        "branch": {"name": branch_name, "head_commit_sha": head_sha},
        "snapshot": {"id": snap_id, "commit_sha": head_sha, "status": "ready"},
        "files": results,
        "meta": {"served_from_cache": True}
    }

def git_list_repositories(owner=None, name=None, visibility=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0140000" if __import__("os").path.isdir("./environment_mix/0140000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _lat_ms(t0):
        return int((time.time() - t0) * 1000)

    def _new_id(prefix):
        return prefix + "_" + hashlib.sha256((prefix + "|" + _now() + "|" + os.urandom(16).hex()).encode("utf-8")).hexdigest()[:24]

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _encode_cursor(last_key):
        raw = json.dumps({"k": last_key}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        import base64
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur.strip():
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string or null")
        import base64
        s = cur.strip()
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        if not isinstance(obj, dict) or "k" not in obj:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        return obj["k"]

    def _log(endpoint, status, message=None, meta=None):
        jobs = _load("fetch_jobs.json")
        ts = _now()
        window_s = 60
        limit_rl = 120
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
        recent = 0
        for j in jobs:
            if j.get("job_type") == "audit_request" and j.get("requested_branch") == endpoint:
                dt = _parse_dt(j.get("created_at"))
                if dt and dt >= cutoff:
                    recent += 1
        if recent >= limit_rl:
            jobs.append({
                "id": _new_id("job"),
                "repository_id": "audit",
                "snapshot_id": None,
                "job_type": "audit_request",
                "requested_branch": endpoint,
                "requested_file_paths": None,
                "status": "failed",
                "attempt": 1,
                "http_status": 429,
                "rate_limit_remaining": 0,
                "error_message": "rate limit exceeded",
                "started_at": ts,
                "finished_at": ts,
                "created_at": ts,
                "updated_at": ts
            })
            _save("fetch_jobs.json", jobs)
            return _err("RATE_LIMIT", "Rate limit exceeded")
        jobs.append({
            "id": _new_id("job"),
            "repository_id": "audit",
            "snapshot_id": None,
            "job_type": "audit_request",
            "requested_branch": endpoint,
            "requested_file_paths": meta,
            "status": "succeeded" if status < 400 else "failed",
            "attempt": 1,
            "http_status": status,
            "rate_limit_remaining": max(0, limit_rl - (recent + 1)),
            "error_message": message,
            "started_at": ts,
            "finished_at": ts,
            "created_at": ts,
            "updated_at": ts
        })
        _save("fetch_jobs.json", jobs)
        return None

    t0 = time.time()

    # Validate filters
    if owner is not None and (not isinstance(owner, str) or not owner.strip()):
        e = _err("VALIDATION_ERROR", "owner must be a non-empty string or null")
        _log("git_list_repositories", 400, e["error"]["message"])
        return {**e, "latency_ms": _lat_ms(t0)}
    if name is not None and (not isinstance(name, str) or not name.strip()):
        e = _err("VALIDATION_ERROR", "name must be a non-empty string or null")
        _log("git_list_repositories", 400, e["error"]["message"])
        return {**e, "latency_ms": _lat_ms(t0)}

    # Tool enum includes "internal" but schema uses "unknown"; treat "internal" as validation error (not supported)
    if visibility is not None:
        if visibility not in ("public", "private", "internal"):
            e = _err("VALIDATION_ERROR", "visibility must be one of: public, private, internal, null")
            _log("git_list_repositories", 400, e["error"]["message"])
            return {**e, "latency_ms": _lat_ms(t0)}
        if visibility == "internal":
            # not representable in schema; real service would likely map, but datastore can't—refuse.
            e = _err("VALIDATION_ERROR", "visibility 'internal' is not supported by this datastore schema")
            _log("git_list_repositories", 400, e["error"]["message"])
            return {**e, "latency_ms": _lat_ms(t0)}

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500")
        _log("git_list_repositories", 400, e["error"]["message"])
        return {**e, "latency_ms": _lat_ms(t0)}

    ckey = _decode_cursor(cursor)
    if isinstance(ckey, dict) and "error" in ckey:
        _log("git_list_repositories", 400, ckey["error"]["message"])
        return {**ckey, "latency_ms": _lat_ms(t0)}

    owner_f = owner.strip() if isinstance(owner, str) else None
    name_f = name.strip() if isinstance(name, str) else None

    repos = _load("github_repositories.json")

    # Filter
    rows = []
    for r in repos:
        if owner_f is not None and r.get("owner") != owner_f:
            continue
        if name_f is not None and r.get("name") != name_f:
            continue
        if visibility is not None:
            if r.get("visibility") != visibility:
                continue
        rows.append(r)

    # Deterministic ordering: (owner, name, id)
    rows.sort(key=lambda r: ((r.get("owner") or ""), (r.get("name") or ""), (r.get("id") or "")))

    # Apply cursor: cursor key is last (owner,name,id) from previous page
    start = 0
    if ckey is not None:
        if (not isinstance(ckey, list)) or len(ckey) != 3 or any(not isinstance(x, str) for x in ckey):
            e = _err("VALIDATION_ERROR", "cursor is invalid")
            _log("git_list_repositories", 400, e["error"]["message"])
            return {**e, "latency_ms": _lat_ms(t0)}
        for i, r in enumerate(rows):
            key = [(r.get("owner") or ""), (r.get("name") or ""), (r.get("id") or "")]
            if key == ckey:
                start = i + 1
                break
        else:
            # Cursor not found; treat as empty page (common API behavior) not error
            start = len(rows)

    page = rows[start:start + limit]
    has_more = (start + limit) < len(rows)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_key = [(last.get("owner") or ""), (last.get("name") or ""), (last.get("id") or "")]
        next_cursor = _encode_cursor(last_key)

    out = []
    for r in page:
        out.append({
            "id": r.get("id"),
            "owner": r.get("owner"),
            "name": r.get("name"),
            "full_name": r.get("full_name"),
            "default_branch": r.get("default_branch"),
            "visibility": r.get("visibility"),
            "last_seen_at": r.get("last_seen_at"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
        })

    resp = {
        "data": out,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": bool(has_more),
            "next_cursor": next_cursor
        },
        "latency_ms": _lat_ms(t0),
    }
    rl = _log("git_list_repositories", 200, None, {"owner": owner, "name": name, "visibility": visibility, "limit": limit, "cursor": cursor})
    if rl:
        return {**rl, "latency_ms": _lat_ms(t0)}
    return resp

def git_get_repository(owner, repo, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0140000" if __import__("os").path.isdir("./environment_mix/0140000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _as_str(x):
        return x if isinstance(x, str) else None

    def _ensure_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    t0 = time.time()
    endpoint = "git_get_repository"
    logs_file = _ensure_logs()

    # Validate inputs
    owner_s = _as_str(owner)
    repo_s = _as_str(repo)
    if owner_s is None or repo_s is None:
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load(logs_file)
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "credential": None,
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": latency_ms,
                "created_at": _now_iso(),
            }
        )
        _save(logs_file, logs)
        return _err("VALIDATION_ERROR", "owner and repo must be strings.")
    if owner_s.strip() == "" or repo_s.strip() == "":
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load(logs_file)
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "credential": None,
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": latency_ms,
                "created_at": _now_iso(),
            }
        )
        _save(logs_file, logs)
        return _err("VALIDATION_ERROR", "owner and repo must be non-empty.")

    repos = _load("github_repositories.json")
    row = None
    for r in repos:
        if isinstance(r, dict) and r.get("owner") == owner_s and r.get("name") == repo_s:
            row = r
            break

    if not row:
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load(logs_file)
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "credential": None,
                "status": "error",
                "error_code": "NOT_FOUND",
                "latency_ms": latency_ms,
                "created_at": _now_iso(),
            }
        )
        _save(logs_file, logs)
        return _err("NOT_FOUND", "Repository is not present in cache.", owner=owner_s, repo=repo_s)

    # Update last_seen_at (observable dynamics)
    now = _now_iso()
    row["last_seen_at"] = now
    row["updated_at"] = now
    # Persist update
    for i, r in enumerate(repos):
        if r.get("id") == row.get("id"):
            repos[i] = row
            break
    _save("github_repositories.json", repos)

    latency_ms = int((time.time() - t0) * 1000)
    logs = _load(logs_file)
    logs.append(
        {
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "credential": None,
            "status": "ok",
            "latency_ms": latency_ms,
            "created_at": _now_iso(),
        }
    )
    _save(logs_file, logs)

    return {"repository": row}

