    filtered = []
    rid = repo_row.get("id")
    for s in snapshots:
        if not isinstance(s, dict):
            continue
        if s.get("repository_id") != rid:
            continue
        if branch is not None and s.get("branch_name") != branch:
            continue
        if commit_sha is not None and s.get("commit_sha") != commit_sha:
            continue
        if status is not None and s.get("status") != status:
            continue
        filtered.append(s)

    # Sort by created_at desc, id desc for stable pagination
    def _key(s):
        ca = s.get("created_at") or ""
        return (ca, s.get("id") or "")

    filtered.sort(key=_key, reverse=True)

    offset = _decode_cursor(cursor)
    if cursor is not None and offset is None:
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load(logs_file)
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "credential": None,
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": latency_ms,
                "created_at": _now_iso(),
            }
        )
        _save(logs_file, logs)
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    if offset is None:
        offset = 0

    page = filtered[offset : offset + limit]
    next_off = offset + len(page)
    has_more = next_off < len(filtered)
    next_cursor = _encode_cursor(next_off) if has_more else None

    latency_ms = int((time.time() - t0) * 1000)
    logs = _load(logs_file)
    logs.append(
        {
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "credential": None,
            "status": "ok",
            "latency_ms": latency_ms,
            "created_at": _now_iso(),
        }
    )
    _save(logs_file, logs)

    return {
        "snapshots": page,
        "pagination": {"total": len(filtered), "limit": limit, "has_more": has_more, "next_cursor": next_cursor},
    }

def git_build_snapshot(owner, repo, branch=None, force=False, expires_in_seconds=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0140000" if __import__("os").path.isdir("./environment_mix/0140000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso():
        return _now().isoformat() + "Z"

    def _ensure_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _new_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{random.randint(1000,9999)}"

    def _is_valid_branch_name(b):
        # Git-like conservative validation: no empty, no spaces/control, no trailing '/', no '..', no '~^:?*[', no backslash
        if not isinstance(b, str) or b.strip() == "":
            return False
        if b != b.strip():
            return False
        bad_chars = set(" ~^:?*[]\\")
        if any((c in bad_chars) for c in b):
            return False
        if ".." in b:
            return False
        if b.endswith("/") or b.startswith("/"):
            return False
        if "//" in b:
            return False
        return True

    t0 = time.time()
    endpoint = "git_build_snapshot"
    logs_file = _ensure_logs()

    # Validate
    if not isinstance(owner, str) or not isinstance(repo, str):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load(logs_file)
        logs.append(
            {"id": _new_id("req"), "endpoint": endpoint, "credential": None, "status": "error", "error_code": "VALIDATION_ERROR", "latency_ms": latency_ms, "created_at": _now_iso()}
        )
        _save(logs_file, logs)
        return _err("VALIDATION_ERROR", "owner and repo must be strings.")
    if owner.strip() == "" or repo.strip() == "":
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load(logs_file)
        logs.append(
            {"id": _new_id("req"), "endpoint": endpoint, "credential": None, "status": "error", "error_code": "VALIDATION_ERROR", "latency_ms": latency_ms, "created_at": _now_iso()}
        )
        _save(logs_file, logs)
        return _err("VALIDATION_ERROR", "owner and repo must be non-empty.")
    if branch is not None and not isinstance(branch, str):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load(logs_file)
        logs.append(
            {"id": _new_id("req"), "endpoint": endpoint, "credential": None, "status": "error", "error_code": "VALIDATION_ERROR", "latency_ms": latency_ms, "created_at": _now_iso()}
        )
        _save(logs_file, logs)
        return _err("VALIDATION_ERROR", "branch must be a string or null.")
    if branch is not None and not _is_valid_branch_name(branch):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load(logs_file)
        logs.append(
            {"id": _new_id("req"), "endpoint": endpoint, "credential": None, "status": "error", "error_code": "VALIDATION_ERROR", "latency_ms": latency_ms, "created_at": _now_iso()}
        )
        _save(logs_file, logs)
        return _err("VALIDATION_ERROR", "Invalid branch name.", branch=branch)
    if not isinstance(force, bool):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load(logs_file)
        logs.append(
            {"id": _new_id("req"), "endpoint": endpoint, "credential": None, "status": "error", "error_code": "VALIDATION_ERROR", "latency_ms": latency_ms, "created_at": _now_iso()}
        )
        _save(logs_file, logs)
        return _err("VALIDATION_ERROR", "force must be boolean.")
    if expires_in_seconds is not None:
        if not isinstance(expires_in_seconds, int) or expires_in_seconds < 60 or expires_in_seconds > 2592000:
            latency_ms = int((time.time() - t0) * 1000)
            logs = _load(logs_file)
            logs.append(
                {"id": _new_id("req"), "endpoint": endpoint, "credential": None, "status": "error", "error_code": "VALIDATION_ERROR", "latency_ms": latency_ms, "created_at": _now_iso()}
            )
            _save(logs_file, logs)
            return _err("VALIDATION_ERROR", "expires_in_seconds must be an integer between 60 and 2592000 or null.")

    repos = _load("github_repositories.json")
    repo_row = None
    for r in repos:
        if isinstance(r, dict) and r.get("owner") == owner and r.get("name") == repo:
            repo_row = r
            break
    if not repo_row:
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load(logs_file)
        logs.append(
            {"id": _new_id("req"), "endpoint": endpoint, "credential": None, "status": "error", "error_code": "NOT_FOUND", "latency_ms": latency_ms, "created_at": _now_iso()}
        )
        _save(logs_file, logs)
        return _err("NOT_FOUND", "Repository is unknown to the cache.", owner=owner, repo=repo)

    rid = repo_row.get("id")
    now_iso = _now_iso()

    # Determine branch to use
    branches = _load("repo_branches.json")
    branch_name = branch

    if branch_name is None:
        # Use repo.default_branch if available, else fall back to existing default branch row if present
        if isinstance(repo_row.get("default_branch"), str) and repo_row["default_branch"].strip() != "":
            branch_name = repo_row["default_branch"]
        else:
            default_row = None
            for b in branches:
                if isinstance(b, dict) and b.get("repository_id") == rid and b.get("is_default") is True:
                    default_row = b
                    break
            if default_row:
                branch_name = default_row.get("name")

    if branch_name is None or not isinstance(branch_name, str) or branch_name.strip() == "":
        # Cannot discover default without GitHub fetch in this endpoint
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load(logs_file)
        logs.append(
            {"id": _new_id("req"), "endpoint": endpoint, "credential": None, "status": "error", "error_code": "VALIDATION_ERROR", "latency_ms": latency_ms, "created_at": _now_iso()}
        )
        _save(logs_file, logs)
        return _err("VALIDATION_ERROR", "Default branch is not known; specify branch explicitly.")

    # Ensure repo_branches row exists and has head_commit_sha (best-effort; offline: deterministic placeholder)
    branch_row = None
    for b in branches:
        if isinstance(b, dict) and b.get("repository_id") == rid and b.get("name") == branch_name:
            branch_row = b
            break

    created_branch = False
    if not branch_row:
        # Create branch row; mark default if matches repo.default_branch
        branch_row = {
            "id": _new_id("br"),
            "repository_id": rid,
            "name": branch_name,
            "head_commit_sha": None,
            "is_default": bool(repo_row.get("default_branch") == branch_name),
            "last_refreshed_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        # Enforce at-most-one default: if setting is_default true, unset others
        if branch_row["is_default"]:
            for ob in branches:
                if isinstance(ob, dict) and ob.get("repository_id") == rid and ob.get("is_default") is True:
                    ob["is_default"] = False
                    ob["updated_at"] = now_iso
        branches.append(branch_row)
        created_branch = True

    # Refresh head_commit_sha best-effort (offline). If missing, synthesize stable pseudo-sha.
    if not isinstance(branch_row.get("head_commit_sha"), str) or branch_row["head_commit_sha"].strip() == "":
        # Pseudo SHA: 40 hex chars derived from owner/repo/branch
        import hashlib

        h = hashlib.sha1(f"{owner}/{repo}@{branch_name}".encode("utf-8")).hexdigest()
        branch_row["head_commit_sha"] = h
    branch_row["last_refreshed_at"] = now_iso
    branch_row["updated_at"] = now_iso

    # Persist branches update (including created)
    for i, b in enumerate(branches):
        if isinstance(b, dict) and b.get("id") == branch_row.get("id"):
            branches[i] = branch_row
            break
    _save("repo_branches.json", branches)

    # Touch repository last_seen_at
    repo_row["last_seen_at"] = now_iso
    repo_row["updated_at"] = now_iso
    for i, r in enumerate(repos):
        if r.get("id") == repo_row.get("id"):
            repos[i] = repo_row
            break
    _save("github_repositories.json", repos)

    commit_sha = branch_row["head_commit_sha"]

    snapshots = _load("repo_snapshots.json")
    jobs = _load("fetch_jobs.json")

    # Find ready snapshot for (rid, branch_name, commit_sha)
    ready = None
    for s in snapshots:
        if not isinstance(s, dict):
            continue
        if s.get("repository_id") == rid and s.get("branch_name") == branch_name and s.get("commit_sha") == commit_sha and s.get("status") == "ready":
            ready = s
            break

    created_snapshot = False
    created_jobs = []

    # If ready exists and not force, return it (no rebuild)
    if ready and not force:
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load(logs_file)
        logs.append(
            {"id": _new_id("req"), "endpoint": endpoint, "credential": None, "status": "ok", "latency_ms": latency_ms, "created_at": _now_iso()}
        )
        _save(logs_file, logs)
        return {"snapshot": ready, "fetch_jobs": []}

    # Else: create or re-queue an expired snapshot for same (rid, branch, commit) or create new queued snapshot.
    target = None
    for s in snapshots:
        if not isinstance(s, dict):
            continue
        if s.get("repository_id") == rid and s.get("branch_name") == branch_name and s.get("commit_sha") == commit_sha:
            # Prefer expired snapshots to requeue
            if s.get("status") == "expired":
                target = s
                break

    ttl = expires_in_seconds if expires_in_seconds is not None else 86400  # service default 24h
    expires_at = (_now() + datetime.timedelta(seconds=ttl)).isoformat() + "Z"

    if target:
        # Transition expired -> queued only
        if target.get("status") != "expired":
            latency_ms = int((time.time() - t0) * 1000)
            logs = _load(logs_file)
            logs.append(
                {"id": _new_id("req"), "endpoint": endpoint, "credential": None, "status": "error", "error_code": "INVALID_TRANSITION", "latency_ms": latency_ms, "created_at": _now_iso()}
            )
            _save(logs_file, logs)
            return _err("INVALID_TRANSITION", "Snapshot cannot be re-queued from current status.", snapshot_id=target.get("id"), status=target.get("status"))
        target["status"] = "queued"
        target["error_message"] = None
        target["expires_at"] = expires_at
        target["updated_at"] = now_iso
        snapshot_row = target
        for i, s in enumerate(snapshots):
            if s.get("id") == snapshot_row.get("id"):
                snapshots[i] = snapshot_row
                break
        _save("repo_snapshots.json", snapshots)
    else:
        # Enforce uniqueness: if a non-ready snapshot exists already for same keys and not force, reuse it.
        existing = None
        for s in snapshots:
            if not isinstance(s, dict):
                continue
            if s.get("repository_id") == rid and s.get("branch_name") == branch_name and s.get("commit_sha") == commit_sha and s.get("status") in ("queued", "building", "failed"):
                existing = s
                break
        if existing and not force:
            snapshot_row = existing
        else:
            snapshot_row = {
                "id": _new_id("snap"),
                "repository_id": rid,
                "branch_name": branch_name,
                "commit_sha": commit_sha,
                "readme_path": None,
                "readme_summary": None,
                "total_files": 0,
                "total_tokens": 0,
                "tokenizer": "unknown",
                "status": "queued",
                "error_message": None,
                "source_fetched_at": None,
                "expires_at": expires_at,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            # uniqueness check
            for s in snapshots:
                if isinstance(s, dict) and s.get("repository_id") == rid and s.get("branch_name") == branch_name and s.get("commit_sha") == commit_sha:
                    # If force and another exists, still do not violate unique constraint: reuse existing
                    snapshot_row = s
                    break
            else:
                snapshots.append(snapshot_row)
                created_snapshot = True
                _save("repo_snapshots.json", snapshots)

    # Create fetch jobs if snapshot is queued and no active build job exists for it
    snapshot_id = snapshot_row.get("id")
    active = None
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("snapshot_id") == snapshot_id and j.get("job_type") == "build_snapshot" and j.get("status") in ("queued", "running"):
            active = j
            break

    if not active:
        job = {
            "id": _new_id("job"),
            "repository_id": rid,
            "snapshot_id": snapshot_id,
            "job_type": "build_snapshot",
            "requested_branch": branch if branch is not None else None,
            "requested_file_paths": None,
            "status": "queued",
            "attempt": 1,
            "http_status": None,
            "rate_limit_remaining": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        jobs.append(job)
        created_jobs.append(job)
        _save("fetch_jobs.json", jobs)

    # Ensure snapshot exists in storage if it was only reused but not saved in this path
    if created_snapshot is False:
        # Still may have modified status/expires_at in place above; ensure saved when changed
        _save("repo_snapshots.json", snapshots)

    latency_ms = int((time.time() - t0) * 1000)
    logs = _load(logs_file)
    logs.append(
        {"id": _new_id("req"), "endpoint": endpoint, "credential": None, "status": "ok", "latency_ms": latency_ms, "created_at": _now_iso()}
    )
    _save(logs_file, logs)

    # Return all jobs linked to this snapshot that were created or already active queued/running
    out_jobs = []
    for j in _load("fetch_jobs.json"):
        if isinstance(j, dict) and j.get("snapshot_id") == snapshot_id and j.get("job_type") == "build_snapshot":
            if j.get("status") in ("queued", "running") or j.get("id") in {x.get("id") for x in created_jobs}:
                out_jobs.append(j)

    return {"snapshot": snapshot_row, "fetch_jobs": out_jobs, "branch": branch_row, "repository": repo_row}

def git_get_fetch_job(job_id, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0140000" if __import__("os").path.isdir("./environment_mix/0140000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_request_logs():
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%y%m%d%H%M%S')}{secrets.token_hex(10)}"

    def _log_request(status, error_code=None, message=None, meta=None, t0=None):
        logs_file = _ensure_request_logs()
        logs = _load(logs_file)
        latency_ms = int((time.time() - t0) * 1000) if isinstance(t0, (int, float)) else None
        logs.append({
            "id": _new_id("req"),
            "endpoint": "git_get_fetch_job",
            "credential": None,
            "status": status,
            "error_code": error_code,
            "message": message,
            "meta": meta,
            "latency_ms": latency_ms,
            "created_at": _now(),
        })
        _save(logs_file, logs)

    def _enforce_rate_limit(t0):
        logs_file = _ensure_request_logs()
        logs = _load(logs_file)
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != "git_get_fetch_job":
                continue
            ts = _dt(r.get("created_at"))
            if ts and ts >= cutoff:
                recent += 1
        if recent >= 240:
            _log_request("error", "RATE_LIMIT", "Rate limit exceeded", t0=t0)
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    t0 = time.time()

    if not isinstance(job_id, str) or not job_id.strip():
        _log_request("error", "VALIDATION_ERROR", "job_id must be a non-empty string.", t0=t0)
        return _err("VALIDATION_ERROR", "job_id must be a non-empty string.")

    rl = _enforce_rate_limit(t0)
    if rl:
        return rl

    jobs = _load("fetch_jobs.json")

    # Relaxed lookup: accept exact id OR (if caller mistakenly passes a repository id) return most recent job for that repository.
    found = None
    for j in jobs:
        if isinstance(j, dict) and j.get("id") == job_id:
            found = j
            break

    if found is None:
        # Fallback: treat as repository_id and return latest job (by created_at) for that repository_id if any.
        candidates = []
        for j in jobs:
            if not isinstance(j, dict):
                continue
            if j.get("repository_id") == job_id:
                candidates.append(j)
        if candidates:
            def _key(x):
                ts = _dt(x.get("created_at"))
                return ts or datetime.datetime.min
            candidates.sort(key=_key, reverse=True)
            found = candidates[0]

    if found is None:
        _log_request("error", "NOT_FOUND", "Fetch job id is unknown.", meta={"job_id": job_id}, t0=t0)
        return _err("NOT_FOUND", "Fetch job id is unknown.", job_id=job_id)

    _log_request("ok", meta={"job_id": found.get("id")}, t0=t0)
    return {"fetch_job": found}
